def _doLogin(self):
    if any(requests.utils.dict_from_cookiejar(self.session.cookies).values()):
        return True
    if self._uid and self._hash:
        requests.utils.add_dict_to_cookiejar(self.session.cookies, self.cookies)
    else:
        params = {'username': self.username,
                  'password': self.password,
                  'login': 'submit'}
        res = self.getURL(self.urls['login'], post_data=params, timeout=30)
        if not res:
            logger.log(u"Unable to connect to provider", logger.WARNING)
            return True
        if re.search('/logout.php', res):
            try:
                if requests.utils.dict_from_cookiejar(self.session.cookies)['uid'] and requests.utils.dict_from_cookiejar(self.session.cookies)['pass']:
                    self._uid = requests.utils.dict_from_cookiejar(self.session.cookies)['uid']
                    self._hash = requests.utils.dict_from_cookiejar(self.session.cookies)['pass']
                    self.cookies = {'uid': self._uid, 'pass': self._hash}
                    return True
            except Exception:
                logger.log(u"Unable to login to provider (cookie)", logger.WARNING)
                return True
        else:
            if re.search('Username does not exist in the userbase or the account is not confirmed yet.', res):
                logger.log(u"Invalid username or password. Check your settings", logger.WARNING)
            if re.search('DDoS protection by CloudFlare', res):
                logger.log(u"Unable to login to provider due to CloudFlare DDoS javascript check", logger.WARNING)
                return True
    return True

